"""Build benchmark_results/LEADERBOARD.md from every <model>/summary.json.

    venv-svr/bin/python -m bench.report
"""
import glob
import json
import os

from bench.common import RESULTS_DIR


def pct(x):
    return '%.1f' % (100 * x)


def main():
    summaries = []
    for path in sorted(glob.glob(os.path.join(RESULTS_DIR, '*', 'summary.json'))):
        with open(path) as f:
            summaries.append(json.load(f))

    lines = ['# Benchmark leaderboard', '',
             'Generated by `bench/report.py` from each model\'s `summary.json`. Lower WER/CER is better; '
             'higher phrase accuracy is better (chance = 10%). 4ch = sites 1, 2, 3, 6.', '',
             '| Model | Device | Ch | WER greedy | WER beam+LM | CER beam+LM | Phrase ID open-vocab | '
             'Phrase ID closed-vocab | Homophene 10 | Homophene 50 | Near-dup 10 | Homophene 10 @1.5x | '
             'Forward ms / 3 s clip | Params |',
             '| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |']
    for s in summaries:
        if 'benchmarks' not in s:  # camera systems (CAM_*) have their own report, CAMERA_BASELINES.md
            continue
        for ch in ('8ch', '6ch', '4ch'):
            if 'open_vocab__' + ch not in s['benchmarks']:
                continue
            ov = s['benchmarks']['open_vocab__' + ch]['metrics']
            def acc(name):
                b = s['benchmarks'].get('%s__%s' % (name, ch))
                return pct(b['metrics']['top1_accuracy']) if b else '-'
            lat = s['latency_3s_clip_forward_ms'][ch]['median']
            device = s['device'] if s['device'] == 'cpu' else s['environment'].get('gpu', s['device'])
            lines.append('| %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %s | %.1f | %.1fM |' % (
                s['model'], device, ch, pct(ov['greedy']['wer']), pct(ov['beam_lm']['wer']), pct(ov['beam_lm']['cer']),
                acc('phrase_id_openvocab'), acc('phrase_id_closedvocab'), acc('homophene_10'), acc('homophene_50'),
                acc('nearduplicate_10'), acc('homophene_10@1.5x'), lat, s['parameters'] / 1e6))

    parity = os.path.join(RESULTS_DIR, 'parity_B0_vs_B1.json')
    if os.path.exists(parity):
        with open(parity) as f:
            p = json.load(f)
        lines += ['', '## Parity (B1 reproduces B0?)', '',
                  '| Check | 8ch | 4ch |', '| --- | --- | --- |']
        for key, label in (('step1_B0_vs_B1_cpu', 'B0 vs B1 CPU: greedy transcripts identical'),
                           ('step2_B1_cpu_vs_B1_gpu', 'B1 CPU vs GPU: greedy transcripts identical')):
            cells = ['%d/%d %s' % (v['greedy_transcripts']['identical'], v['greedy_transcripts']['n'],
                                   'PASS' if v['pass'] else 'FAIL') for v in (p[key]['8ch'], p[key]['4ch'])]
            lines.append('| %s | %s | %s |' % (label, cells[0], cells[1]))
        d = p['step3_ctcdecode_vs_svr_decoder_on_B0_logits']
        cells = ['%s vs %s (%s)' % (pct(v['beam_lm_wer']['ctcdecode']), pct(v['beam_lm_wer']['svr_decoder']),
                                     'PASS' if v['pass'] else 'FAIL') for v in (d['8ch'], d['4ch'])]
        lines.append('| ctcdecode vs our decoder on B0 log-probs: beam+LM WER %% | %s | %s |' % (cells[0], cells[1]))
        if 'B0_official_script' in p:
            lines += ['', "B0 WER from Gaddy's own `recognition_model.py --evaluate_saved`: **%s%%**."
                      % pct(p['B0_official_script']['wer'])]
    out = os.path.join(RESULTS_DIR, 'LEADERBOARD.md')
    with open(out, 'w') as f:
        f.write('\n'.join(lines) + '\n')
    print('wrote', out)


if __name__ == '__main__':
    main()
